.filenamespace copyscreen_RLE
// 10 SYS (2064)

//*=$0801

//        BYTE    $0E, $08, $0A, $00, $9E, $20, $28,  $32, $30, $36, $34, $29, $00, $00, $00


        //LDA #$0E
        //JSR $FFD2 // Switch to lower-case charset
        
// ------------------------------------------------------------
// RLE Demo for CBM PRG Studio
// ------------------------------------------------------------
// This code decompresses RLE-encoded screen and color data
// into the C64"s screen memory ($0400) and color memory ($D800).
// ------------------------------------------------------------


// ------------------------------------------------------------
// Main Code Starts at $0810
// ------------------------------------------------------------
//        * = $0810

StartCopyScreen:
//        LDA #$0E
//        JSR $FFD2 // Switch to lower-case charset
        jmp Init

// ------------------------------------------------------------
// Zero-page Pointers and Variables
// ------------------------------------------------------------
.label srcPtr  = $FB    // Low .byte at $FB, High .byte at $FC
.label destPtr = $FD    // Low .byte at $FD, High .byte at $FE
.label runVal  = $FF    // Single .byte at $FF

// ------------------------------------------------------------
// Constants for Screen and Color Memory
// ------------------------------------------------------------
.label SCREENRAM = $0400
.label COLOURRAM = $D800

// ------------------------------------------------------------
// Initialization Routine
// ------------------------------------------------------------
Init:
        sei                    // Disable interrupts
        cld                    // Clear decimal mode

        // 1) Decompress RLE screen data into $0400
        lda #<ScreenRLEData
        sta srcPtr              // Store low .byte of ScreenRLEData
        lda #>ScreenRLEData
        sta srcPtr+1            // Store high .byte of ScreenRLEData

        lda #<SCREENRAM
        sta destPtr             // Store low .byte of SCREENRAM ($0400)
        lda #>SCREENRAM
        sta destPtr+1           // Store high .byte of SCREENRAM

        jsr RLEDecode           // Decompress screen data

        // 2) Decompress RLE color data into $D800
        lda #<ColorRLEData
        sta srcPtr              // Store low .byte of ColorRLEData
        lda #>ColorRLEData
        sta srcPtr+1            // Store high .byte of ColorRLEData

        lda #<COLOURRAM
        sta destPtr             // Store low .byte of COLOURRAM ($D800)
        lda #>COLOURRAM
        sta destPtr+1           // Store high .byte of COLOURRAM

        jsr RLEDecode           // Decompress color data

        // 3) Return control to BASIC
        rts                     // Return to BASIC

// ------------------------------------------------------------
// RLEDecode Subroutine
// ------------------------------------------------------------
RLEDecode:
DecodeLoop:
        

        // Load ByteVal
        ldy #0
                                 
        lda (srcPtr),y        // y=0: Load ByteVal
        sta runVal             // Store ByteVal in runVal

        // Load Run Length
        iny
        lda (srcPtr),y        // y=1: Load RunLen
        beq DoneDecode         // If RunLen == 0, exit

        // Transfer RunLen to X register
        tax                     // X = RunLen

        // Increment srcPtr by 2 to point to the next [RunLen][ByteVal] pair
        lda srcPtr
        clc
        adc #2
        sta srcPtr             // Increment low .byte of srcPtr
        lda srcPtr+1
        adc #0
        sta srcPtr+1           // Increment high .byte of srcPtr

        // Reset Y for StoreLoop
        ldy #0                  // Initialize Y=0 for StoreLoop

StoreLoop:
        // Store ByteVal into destPtr
        lda runVal              // Load ByteVal
        sta (destPtr),y        // Store at (destPtr + y)

        // Increment destPtr to point to the next memory location
        inc destPtr             // Increment destPtr low .byte
        bne SkipDestInc         // If no carry, skip high .byte increment
        inc destPtr+1           // If carry occurred, increment destPtr high .byte
SkipDestInc:

        // Decrement X (RunLen) and loop if not zero
        dex                     // Decrement X
        bne StoreLoop           // If X != 0, continue StoreLoop

        // Jump back to DecodeLoop to process the next [RunLen][ByteVal] pair
        jmp DecodeLoop

DoneDecode:
        rts                     // Return from subroutine



